import React from "react";
import { Link } from "react-router-dom";
import SectionShell from "../layout/SectionShell";
import { revealRef } from "../../hooks/useReveal";
import useLang from "../../hooks/useLang";
import { getProjectPath } from "../../utils/localeRouting";
import {
  competitions,
  credentials,
  labNotes,
  principles,
  training,
} from "../../content/records";

const pick = (value, lang) =>
  value && typeof value === "object" ? value[lang] ?? value.ko : value;

// Short lab write-ups without a detail page: period, title, one line, stack.
export const LabNotes = () => {
  const lang = useLang();

  return (
    <SectionShell id="labs" className="history records">
      <ol className="history-list">
        {labNotes.map((lab) => (
          <li className="history-row" key={lab.id} data-reveal ref={revealRef}>
            <span className="history-period mono">{lab.period}</span>
            <div className="history-role">
              <h3>{pick(lab.title, lang)}</h3>
              <div className="chip-list record-chips">
                {lab.stack.map((tech) => (
                  <span className="chip" key={tech}>
                    {tech}
                  </span>
                ))}
              </div>
            </div>
            <p className="history-desc">{pick(lab.note, lang)}</p>
          </li>
        ))}
      </ol>
    </SectionShell>
  );
};

// Awards and selections first, then finals, participation, and submissions,
// so a prize is never read at the same weight as an entry.
const competitionGroups = [
  {
    id: "won",
    label: { ko: "수상과 선정", en: "Awards and selections" },
    items: competitions.filter((item) => item.award),
  },
  {
    id: "entered",
    label: { ko: "본선 진출, 참가, 제출", en: "Finals, participation, and submissions" },
    items: competitions.filter((item) => !item.award),
  },
];

export const Competitions = () => {
  const lang = useLang();

  return (
    <SectionShell id="awards" className="history records">
      {competitionGroups.map((group) => (
        <React.Fragment key={group.id}>
          <div className="sub-head">
            <p className="kicker">{pick(group.label, lang)}</p>
            <p className="kicker">{String(group.items.length).padStart(2, "0")}</p>
          </div>
          <ol className="history-list">
            {group.items.map((item) => {
              const name = pick(item.name, lang);

              return (
                <li
                  className={`history-row${item.award ? " is-award" : ""}`}
                  key={`${item.period}-${name}`}
                  data-reveal
                  ref={revealRef}
                >
                  <span className="history-period mono">{item.period}</span>
                  <div className="history-role">
                    <h3>
                      {item.slug ? (
                        <Link to={getProjectPath(lang, item.slug)} className="record-link">
                          {name}
                        </Link>
                      ) : (
                        name
                      )}
                    </h3>
                  </div>
                  <p className="history-desc record-result">{pick(item.result, lang)}</p>
                </li>
              );
            })}
          </ol>
        </React.Fragment>
      ))}
    </SectionShell>
  );
};

// Training programmes with their key facts, then language and certificates.
export const Training = () => {
  const lang = useLang();

  return (
    <SectionShell id="training" className="history records">
      <ol className="history-list">
        {training.map((item) => (
          <li className="history-row" key={item.period} data-reveal ref={revealRef}>
            <span className="history-period mono">{item.period}</span>
            <div className="history-role">
              <h3>{pick(item.name, lang)}</h3>
            </div>
            <ul className="history-desc record-lines">
              {pick(item.lines, lang).map((line) => (
                <li key={line}>{line}</li>
              ))}
            </ul>
          </li>
        ))}
        {credentials.map((item) => {
          const name = pick(item.name, lang);

          return (
            <li className="history-row" key={name} data-reveal ref={revealRef}>
              <span className="history-period mono">{item.date}</span>
              <div className="history-role">
                <h3>{name}</h3>
              </div>
              <p className="history-desc record-result">{pick(item.value, lang)}</p>
            </li>
          );
        })}
      </ol>
    </SectionShell>
  );
};

// Working principles: number, principle, and the cases behind it.
export const Principles = () => {
  const lang = useLang();

  return (
    <SectionShell id="principles" className="history records principles">
      <ol className="history-list">
        {principles.map((item, index) => (
          <li className="history-row" key={item.id} data-reveal ref={revealRef}>
            <span className="history-period mono">{String(index + 1).padStart(2, "0")}</span>
            <div className="history-role">
              <h3>{pick(item.title, lang)}</h3>
            </div>
            <div className="history-desc">
              {item.quote ? (
                <blockquote className="principle-quote">
                  <p lang="ko">{item.quote.text}</p>
                  <cite>{pick(item.quote.source, lang)}</cite>
                </blockquote>
              ) : null}
              <ul className="record-lines principle-cases">
                {pick(item.cases, lang).map((line) => (
                  <li key={line}>{line}</li>
                ))}
              </ul>
            </div>
          </li>
        ))}
      </ol>
    </SectionShell>
  );
};
